-- Generated by generate_wotlk.py (3.3.5a port). Do not edit by hand.
local _, ns = ...

-- Runs after Data/Instances.lua, Data/Loot.lua, Data/TBC/* and Data/WotLK/{Instances,Loot}.lua.
-- Every block mutates existing era/TBC records defensively: a missing instance, encounter or
-- item is skipped silently, so a data change elsewhere can never break loading.
local instances = ns.Data and ns.Data.instances
local loot = ns.Data and ns.Data.loot
if type(instances) ~= "table" or type(loot) ~= "table" then
    return
end

local function GetBoss(instanceKey, bossKey)
    local instanceLoot = loot[instanceKey]
    local boss = type(instanceLoot) == "table" and instanceLoot[bossKey] or nil
    if type(boss) == "table" then
        return boss
    end
    return nil
end

local function MarkExcluded(record)
    if type(record.excludedFlavors) ~= "table" then
        record.excludedFlavors = {}
    end
    record.excludedFlavors.wotlk = true
end

-- The questID corrections below are only right on a 3.3.5a realm; this file is only listed in
-- the 3.3.5a TOC, but check the flavor anyway.
local function IsWotlkClient()
    local constants = ns.Constants
    if type(constants) ~= "table" or type(constants.GetClientFlavor) ~= "function" then
        return false
    end
    local ok, flavor = pcall(constants.GetClientFlavor)
    return ok and flavor == constants.CLIENT_WOTLK
end

