for _, exclusion in ipairs(exclusions) do
    local boss = GetBoss(exclusion.instanceKey, exclusion.bossKey)
    if boss then
        if exclusion.itemID then
            for _, item in ipairs(type(boss.items) == "table" and boss.items or {}) do
                if type(item) == "table" and item.itemID == exclusion.itemID then
                    MarkExcluded(item)
                end
            end
        else
            MarkExcluded(boss)
        end
    end
end

