-- Position in instance.bosses: right after insertAfter when it is listed, else appended.
local holidayPlacements = {
    { instanceKey = "blackrock_depths", bossKey = "coren_direbrew", insertAfter = "phalanx" },
    { instanceKey = "scarlet_monastery", bossKey = "headless_horseman", insertAfter = "bloodmage_thalnos" },
    { instanceKey = "the_slave_pens", bossKey = "ahune" },
    { instanceKey = "shadowfang_keep", bossKey = "apothecary_hummel", insertAfter = "fel_steed" },
}

for _, placement in ipairs(holidayPlacements) do
    local instance = instances[placement.instanceKey]
    local instanceLoot = loot[placement.instanceKey]
    local record = holidayBosses[placement.instanceKey]
        and holidayBosses[placement.instanceKey][placement.bossKey]
    if type(instance) == "table" and type(instanceLoot) == "table" and record
        and instanceLoot[placement.bossKey] == nil then
        instanceLoot[placement.bossKey] = record
        if type(instance.bosses) ~= "table" then
            instance.bosses = {}
        end
        local listed = false
        local position
        for index, bossKey in ipairs(instance.bosses) do
            if bossKey == placement.bossKey then
                listed = true
            end
            if placement.insertAfter and bossKey == placement.insertAfter then
                position = index + 1
            end
        end
        if not listed then
            table.insert(instance.bosses, position or (#instance.bosses + 1), placement.bossKey)
        end
    end
end

-- 4. Corrections that are certain for 3.3.5a (each with its reason).
local corrections = {
    -- Vashj's Vial Remnant: quest 10445 The Vials of Eternity was removed in 3.0.2 and replaced by
    -- the identical quest 13432 (no Hand of A'dal title); on 3.3.5a the item is an objective of
    -- 13432.
    -- Source: https://warcraft.wiki.gg/wiki/Quest:The_Vials_of_Eternity
    { instanceKey = "serpentshrine_cavern", bossKey = "lady_vashj", itemID = 29906, field = "questID", value = 13432 },
    -- Kael's Vial Remnant: same replacement 10445 -> 13432 since 3.0.2.
    -- Source: https://warcraft.wiki.gg/wiki/Quest:The_Vials_of_Eternity
    { instanceKey = "the_eye", bossKey = "kaelthas_sunstrider", itemID = 29905, field = "questID", value = 13432 },
    -- Earthen Signet: quest 10901 The Cudgel of Kar'desh was removed in 3.0.2 and replaced by the
    -- identical quest 13431 (no Champion of the Naaru title).
    -- Source: https://warcraft.wiki.gg/wiki/The_Cudgel_of_Kar%27desh
    { instanceKey = "gruuls_lair", bossKey = "gruul_the_dragonkiller", itemID = 31750, field = "questID", value = 13431 },
    -- Blazing Signet: same replacement 10901 -> 13431 since 3.0.2.
    -- Source: https://warcraft.wiki.gg/wiki/The_Cudgel_of_Kar%27desh
    { instanceKey = "karazhan", bossKey = "nightbane", itemID = 31751, field = "questID", value = 13431 },
    -- Magtheridon's Head 32385 starts only the Alliance quest 11002; the Horde quest 11003 starts
    -- from a separate item 32386 (see appendItem entry).
    -- Source: local: Questie-335 Database/Wotlk/wotlkQuestDB.lua [11002] The Fall of Magtheridon
    -- requiredRaces 1101 (Alliance) startedBy item 32385, [11003] requiredRaces 690 (Horde)
    -- startedBy item 32386
    { instanceKey = "magtheridons_lair", bossKey = "magtheridon", itemID = 32385, field = "questIDs", value = { 11002 } },
    -- 32385 is the Alliance copy of Magtheridon's Head (quest 11002, requiredRaces 1101).
    -- Source: local: Questie-335 Database/Wotlk/wotlkQuestDB.lua [11002] The Fall of Magtheridon
    -- requiredRaces 1101 (Alliance) startedBy item 32385, [11003] requiredRaces 690 (Horde)
    -- startedBy item 32386
    { instanceKey = "magtheridons_lair", bossKey = "magtheridon", itemID = 32385, field = "factionAvailability", value = "alliance" },
    -- Horde copy of Magtheridon's Head (starts quest 11003 The Fall of Magtheridon, requiredRaces
    -- 690) is missing from Revival; append it right after 32385.
    -- Source: local: Questie-335 Database/Wotlk/wotlkQuestDB.lua [11002] The Fall of Magtheridon
    -- requiredRaces 1101 (Alliance) startedBy item 32385, [11003] requiredRaces 690 (Horde)
    -- startedBy item 32386
    { instanceKey = "magtheridons_lair", bossKey = "magtheridon", appendAfter = 32385, appendItem = { itemID = 32386, category = "startsQuest", difficulties = { normal = true }, questID = 11003, condition = "factionSpecificQuestStart", factionAvailability = "horde", dropChanceStatus = "unverified" } },
}

if IsWotlkClient() then
    for _, correction in ipairs(corrections) do
        local boss = GetBoss(correction.instanceKey, correction.bossKey)
        if boss and type(boss.items) == "table" then
            if correction.appendItem then
                local exists = false
                local position
                for index, item in ipairs(boss.items) do
                    if type(item) == "table" then
                        if item.itemID == correction.appendItem.itemID then
                            exists = true
                        end
                        if item.itemID == correction.appendAfter then
                            position = index + 1
                        end
                    end
                end
                if not exists then
                    table.insert(boss.items, position or (#boss.items + 1), correction.appendItem)
                end
            else
                for _, item in ipairs(boss.items) do
                    if type(item) == "table" and item.itemID == correction.itemID then
                        item[correction.field] = correction.value
                    end
                end
            end
        end
    end
end
